//! Service handlers that need tracing instrumentation.
use tracing::instrument;

#[derive(Debug)]
pub struct Request {
    pub id: u64,
    pub user_id: u64,
    pub action: String,
}

#[derive(Debug)]
pub struct Response {
    pub request_id: u64,
    pub success: bool,
    pub message: String,
}

/// Process a request. Add #[instrument] with request.id and user_id as fields.
pub async fn process_request(request: Request) -> Response {
    // TODO: add #[instrument] attribute
    let result = validate_action(&request.action).await;
    Response {
        request_id: request.id,
        success: result,
        message: if result { "ok".into() } else { "invalid action".into() },
    }
}

/// Validate action string.
async fn validate_action(action: &str) -> bool {
    // TODO: add #[instrument(fields(action = %action))]
    !action.is_empty() && action.len() < 100
}

#[cfg(test)]
mod tests {
    use super::*;
    use tracing_test::traced_test;

    #[tokio::test]
    async fn test_process_valid_request() {
        let req = Request { id: 1, user_id: 42, action: "login".into() };
        let resp = process_request(req).await;
        assert!(resp.success);
        assert_eq!(resp.request_id, 1);
    }

    #[tokio::test]
    async fn test_process_empty_action() {
        let req = Request { id: 2, user_id: 42, action: "".into() };
        let resp = process_request(req).await;
        assert!(!resp.success);
    }

    #[tokio::test]
    #[traced_test]
    async fn test_spans_emitted() {
        let req = Request { id: 99, user_id: 7, action: "read".into() };
        process_request(req).await;
        // traced_test captures log output — just verify no panic
        // and the function completed
    }
}
